//! The [`OfflineModel`] extension trait.

use super::{BoundTo, Offline};

use crate::Model;
use crate::model::offline::ConflictStrategy;

/// A model stored in the client's local SQLite database, generated by `#[model(offline)]`.
pub trait OfflineModel: BoundTo<Offline> + Model {
    /// The SQLite table name for this model.
    const SQLITE_TABLE: &'static str;

    /// Hash of the model's fields; it changes when a field is added, removed, renamed or retyped.
    const SCHEMA_VERSION: u64;

    /// Whether an incompatible schema change needs a manual migration instead of recreating the table.
    const PRESERVE_DATA: bool;

    /// How a record changed both locally and on the server is resolved.
    const CONFLICT_RESOLUTION: ConflictStrategy = ConflictStrategy::LastWriteWins;

    /// Whether this model is soft-deletable (`#[model(soft_delete)]`).
    const SOFT_DELETE: bool = false;

    /// The framework-managed soft-delete timestamp column name.
    const DELETED_AT_COLUMN: &'static str = "deleted_at";

    /// Returns the `CREATE TABLE` statement for this model.
    fn create_table_sql() -> &'static str;

    /// Returns the column names for this model.
    fn column_names() -> &'static [&'static str];

    /// Returns column definitions as (name, sql_type, nullable) tuples.
    fn column_definitions() -> &'static [(&'static str, &'static str, bool)];

    /// Columns holding a [`Localized`](crate::i18n::Localized) field's source-locale value.
    fn translatable_columns() -> &'static [&'static str] {
        &[]
    }

    /// The companion table of per-locale values (`<table>_i18n`), if any field is translatable.
    fn translation_table() -> Option<&'static str> {
        None
    }

    /// The `CREATE TABLE` statement for the companion translations table, if any.
    fn translation_table_sql() -> Option<&'static str> {
        None
    }
}
